from typing import TypeVar, List

T = TypeVar("T")

def last_n_unique(lst: List[T], n: int) -> List[T]:
    """
    Return the last `n` unique elements from `lst`, preserving their original (left-to-right) order.

    Scans the list from the end to find elements by their last occurrence, collects up to `n`
    distinct elements, and returns them in the same order they appear in `lst`.

    Parameters:
        lst: List of elements (elements may be unhashable).
        n: Number of unique elements to return. If n <= 0, an empty list is returned.

    Returns:
        A list of up to `n` unique elements from `lst`, in original order.
    """
    if n <= 0:
        return []

    seen_list: List[T] = []
    seen_set = set()

    for x in reversed(lst):
        seen_flag = False
        try:
            # Try the fast path (hashable elements)
            if x in seen_set:
                seen_flag = True
        except TypeError:
            # Unhashable element: fall back to list membership check
            if x in seen_list:
                seen_flag = True

        if not seen_flag:
            try:
                seen_set.add(x)
            except TypeError:
                # element unhashable: ignore set addition
                pass
            seen_list.append(x)
            if len(seen_list) >= n:
                break

    # seen_list is in reversed original order (last seen first); reverse it back
    return list(reversed(seen_list))

